function mc(prompt, options, correctIndex, explanation) {
  return { prompt, type: "multiple_choice", options, correctIndex, explanation };
}
function tf(prompt, correctTrue, explanation) {
  return {
    prompt,
    type: "true_false",
    options: ["True", "False"],
    correctIndex: correctTrue ? 0 : 1,
    explanation,
  };
}

